import React, { useEffect, useState } from 'react';
import { Button } from '../ui/button';
import { Label } from '../ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { AlertTriangle } from 'lucide-react';
import { adminUsers } from '../../lib/api';

const LABELS = {
  leads: 'Leads', schools: 'Schools', contacts: 'Contacts', tasks: 'Tasks',
  followups: 'Follow-ups', visit_plans: 'Visit plans', visits: 'Visits',
  field_visits: 'Field visits', del_task_instances: 'Delegated tasks',
};

export function DeleteUserDialog({ open, onOpenChange, user, users, onConfirm }) {
  const [summary, setSummary] = useState(null);
  const [loadError, setLoadError] = useState(false);
  const [transferTo, setTransferTo] = useState('');
  const [busy, setBusy] = useState(false);

  const textPri = 'text-[var(--text-primary)]';
  const textSec = 'text-[var(--text-secondary)]';
  const textMuted = 'text-[var(--text-muted)]';

  useEffect(() => {
    if (!open || !user) return;
    setSummary(null);
    setLoadError(false);
    setTransferTo('');
    adminUsers.dataSummary(user.user_id)
      .then(res => setSummary(res.data))
      .catch(() => setLoadError(true));
  }, [open, user]);

  if (!user) return null;

  const candidates = (users || []).filter(u => u.user_id !== user.user_id && u.is_active !== false);
  const total = summary?.total ?? null;

  // How much of the live work is CRM (leads / schools / contacts) — the backend
  // decides which collections those are, next to the gate that filters them.
  const crmCount = summary?.crm_total ?? 0;
  const recipient = candidates.find(u => u.email === transferTo);
  // `can_receive_crm` is computed server-side from the same rule as the CRM read
  // gate. Older payloads won't carry it — treat missing as "fine" so a stale
  // frontend never invents a scary warning.
  const recipientBlindToCrm =
    !!recipient && recipient.can_receive_crm === false && crmCount > 0;

  const confirm = async () => {
    setBusy(true);
    try {
      await onConfirm(user.user_id, transferTo);
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className={`bg-[var(--bg-card)] border-[var(--border-color)] ${textPri} w-[calc(100vw-1rem)] sm:max-w-lg`}>
        <DialogHeader>
          <DialogTitle className={`${textPri} text-lg flex items-center gap-2`}>
            <AlertTriangle className="h-5 w-5 text-[#e94560]" />
            Remove {user.name}?
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <p className={`text-sm ${textSec}`}>
            The account is deactivated, not erased. Past quotations, orders and history keep this
            person's name — only live work needs a new owner.
          </p>

          <div className="rounded-md border border-[var(--border-color)] p-3">
            <p className={`text-xs uppercase tracking-wide ${textMuted} mb-2`}>Live work owned</p>
            {loadError && (
              <p className="text-sm text-[#e94560]">
                Could not load how much live work this person owns. Removal is blocked until this
                can be checked — try again in a moment.
              </p>
            )}
            {!loadError && summary === null && <p className={`text-sm ${textMuted}`}>Counting…</p>}
            {!loadError && summary && total === 0 && (
              <p className={`text-sm ${textMuted}`}>Nothing assigned — nothing to transfer.</p>
            )}
            {!loadError && summary && total > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {Object.entries(summary.counts).map(([k, v]) => (
                  <span key={k} className="text-xs px-2 py-0.5 rounded-full border border-[var(--border-color)] bg-[var(--bg-hover)]">
                    {v} {LABELS[k] || k}
                  </span>
                ))}
              </div>
            )}
          </div>

          {!loadError && summary && total > 0 && (
            <div>
              <Label className={`${textSec} text-xs uppercase tracking-wide mb-1.5 block`}>Give this work to</Label>
              <Select value={transferTo} onValueChange={setTransferTo}>
                <SelectTrigger className="bg-[var(--bg-primary)] border-[var(--border-color)]">
                  <SelectValue placeholder="Select a user…" />
                </SelectTrigger>
                <SelectContent className="bg-[var(--bg-card)] border-[var(--border-color)]">
                  {candidates.map(u => (
                    <SelectItem key={u.user_id} value={u.email} className={`${textPri} hover:bg-[var(--bg-hover)]`}>
                      {u.name} — {u.email}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {!transferTo && (
                <p className="text-[11px] text-[#e94560] mt-1.5">
                  Pick someone, or this work will be left with no owner.
                </p>
              )}
              {/* Warn, never block: an admin may deliberately park records with
                  someone they are about to grant CRM access to. */}
              {recipientBlindToCrm && (
                <div className="mt-2 rounded-md border border-yellow-500/40 bg-yellow-500/10 p-2.5 flex gap-2">
                  <AlertTriangle className="h-4 w-4 text-yellow-500 flex-shrink-0 mt-0.5" />
                  <p className="text-[11px] text-yellow-500 leading-snug">
                    {recipient.name} does not have CRM access, so they will not be able to see
                    the {crmCount} leads, schools and contacts you are giving them. The records
                    will still move. Give {recipient.name} the Leads module in User Management
                    and they will show up.
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} className={`border-[var(--border-color)] ${textSec}`}>Cancel</Button>
          <Button onClick={confirm}
            disabled={busy || loadError || summary === null || (total > 0 && !transferTo)}
            className="bg-[#e94560] hover:bg-[#f05c75] text-white">
            {busy ? 'Working…' : 'Deactivate & transfer'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
